import {useEffect,useState} from 'react';import api,{message} from '../services/api.js';
export default function Audit(){const [rows,setRows]=useState([]),[error,setError]=useState('');useEffect(()=>{api.get('/audit').then(r=>setRows(r.data)).catch(e=>setError(message(e)))},[]);return <><div className="page-head"><div><h2>Audit Log</h2><p>Recent administrative actions.</p></div></div>{error&&<div className="alert error">{error}</div>}<div className="panel table-wrap"><table><thead><tr><th>Time</th><th>User</th><th>Action</th><th>Entity</th><th>Details</th></tr></thead><tbody>{rows.map(r=><tr key={r._id}><td>{new Date(r.createdAt).toLocaleString()}</td><td>{r.user?.name||'—'}</td><td>{r.action}</td><td>{r.entity||'—'}</td><td>{r.details||'—'}</td></tr>)}{!rows.length&&<tr><td colSpan="5" className="empty">No activity yet.</td></tr>}</tbody></table></div></>}
